import { FC, HTMLAttributes } from 'react';

import { Badge, Button, Radio } from 'antd';
import cn from 'classnames';

import { NoResult, NotificationCard } from 'entities/Notification';
import { NotificationsFilters } from 'features/Filters';
import { EFilters } from 'features/Filters/model/enums';
import { NotificationsCategories } from 'features/NotificationsCategories';
import { EDefaultOptions, EMainRoutes } from 'shared/typings';
import { OverlayLoader } from 'shared/ui';

import { useNotificationsList } from '../../hooks/useNotificationsList';

import styles from './NotificationsList.module.scss';

interface INotificationsListProps extends HTMLAttributes<HTMLDivElement> {}

export const NotificationsList: FC<INotificationsListProps> = ({ className, ...props }) => {
	const {
		t,
		isMobile,
		getALLFilterValues,
		notifications,
		total,
		isFetching,
		unread,
		loadMoreRef,
		navigate,
		onFilterChange,
		appendReadNotification,
		onMarkAll,
	} = useNotificationsList();

	return (
		<div {...props} className={cn(className, styles.notificationsList)}>
			<div className={styles.main}>
				<div className={styles.menu}>
					<Radio.Group
						onChange={(value) => onFilterChange(EFilters.READ, value.target.value)}
						buttonStyle={'solid'}
						size={'large'}
						block={isMobile}
						value={getALLFilterValues(EFilters.READ) || EDefaultOptions.ALL}>
						<Radio.Button value={EDefaultOptions.ALL}>{t('All')}</Radio.Button>
						<Radio.Button value={'false'}>
							{t('New')}
							<Badge count={unread?.unread_count} offset={[5, -10]} />
						</Radio.Button>
					</Radio.Group>

					<Button onClick={onMarkAll} type={'link'} size={'large'} block={isMobile}>
						{t('Mark all as read')}
					</Button>

					{isMobile && (
						<>
							<NotificationsFilters />
							<NotificationsCategories />
						</>
					)}
				</div>

				<div className={styles.list}>
					{isFetching && <OverlayLoader />}

					{!!total &&
						notifications.map((notification) => (
							<NotificationCard
								key={notification.id}
								notification={notification}
								appendReadNotification={appendReadNotification}
							/>
						))}

					{!total && <NoResult onNavigate={() => navigate(`/${EMainRoutes.CATALOG}`)} />}
				</div>

				<div ref={loadMoreRef}></div>
			</div>

			{!isMobile && (
				<div className={styles.sidebar}>
					<NotificationsCategories />
					<NotificationsFilters />
				</div>
			)}
		</div>
	);
};
