import { FC, HTMLAttributes, useEffect, useState } from 'react';
import { useTranslation } from 'react-i18next';

import { Button } from 'antd';
import cn from 'classnames';

import AngleIcon from 'assets/images/icons/angle-down.svg?react';
import { NOTIFICATIONS_CATEGORIES } from 'entities/Notification';
import { useFilters } from 'features/Filters';
import { EFilters } from 'features/Filters/model/enums';
import { useMedia } from 'shared/hooks';

import styles from './NotificationsCategories.module.scss';

interface INotificationsCategoriesProps extends HTMLAttributes<HTMLDivElement> {}

export const NotificationsCategories: FC<INotificationsCategoriesProps> = ({ className, ...props }) => {
	const isMobile = useMedia();
	const { t } = useTranslation();
	const { getALLFilterValues, onFilterChange } = useFilters();
	const selectedCategory = getALLFilterValues(EFilters.CATEGORY)?.[0];
	const [isOpened, setIsOpened] = useState(!isMobile);

	useEffect(() => {
		setIsOpened(!isMobile);
	}, [isMobile]);

	const onCategoryChange = (category: string) => {
		const newCategory = category === selectedCategory ? [] : [category];
		onFilterChange(EFilters.CATEGORY, newCategory);
	};

	return (
		<div {...props} className={cn(className, styles.notificationsCategories)}>
			{isMobile && (
				<Button
					className={styles.button}
					type={'default'}
					icon={<AngleIcon />}
					iconPosition={'end'}
					size={'large'}
					block
					onClick={() => setIsOpened(!isOpened)}>
					{t('Categories')}
				</Button>
			)}

			<div className={cn(styles.categories, { [styles.opened]: isOpened || !isMobile })}>
				{Object.entries(NOTIFICATIONS_CATEGORIES).map(([key, { name, icon }]) => (
					<Button
						className={styles.categoryBtn}
						icon={icon}
						color={'default'}
						variant={selectedCategory === key ? 'filled' : 'text'}
						size={'large'}
						key={name}
						onClick={() => onCategoryChange(key)}>
						{name}
					</Button>
				))}
			</div>
		</div>
	);
};
