import { RefObject, useEffect } from 'react';

import { EPagination } from 'features/Pagination';

import { useCommonSlice } from './useCommonSlice';
import { useInView } from './useInView';

export const useInfinityScroll = (
	ref: RefObject<HTMLElement | null> | null,
	total: number = 0,
	loadCount: number = EPagination.MIN,
	diff: number = 0,
) => {
	const { infinityScrollOffset, infinityScrollPage, setInfinityScrollOffset, setInfinityScrollPage } = useCommonSlice();

	const loadMoreInView = useInView(ref, { rootMargin: '300px' });

	useEffect(() => {
		const hasMore = total - infinityScrollOffset > loadCount;
		const newOffset = infinityScrollPage * loadCount - diff;

		if (loadMoreInView && hasMore && newOffset >= 0) {
			setInfinityScrollOffset(newOffset);
			setInfinityScrollPage(infinityScrollPage + 1);
		}
	}, [loadMoreInView]); // eslint-disable-line
};
