import { useEffect, useRef } from 'react';
import { useTranslation } from 'react-i18next';
import { useDispatch, useSelector } from 'react-redux';
import { useNavigate, useSearchParams } from 'react-router-dom';

import { RootState } from 'app/appStore';
import {
	clearReadNotifications,
	setReadNotifications,
	useNotificationsListQuery,
	useNotificationsUnreadCountRetrieveQuery,
	useReadNotifications,
} from 'entities/Notification';
import { EFilters, getUrlParamsForApi, useFilters } from 'features/Filters';
import { EPagination } from 'features/Pagination';
import { useCommonSlice, useInfinityScroll, useMedia } from 'shared/hooks';

export const useNotificationsList = () => {
	const navigate = useNavigate();
	const { t } = useTranslation();
	const isMobile = useMedia();
	const dispatch = useDispatch();
	const { getALLFilterValues, getFilterValue, onFilterChange } = useFilters();
	const { appendReadNotification, setRead } = useReadNotifications();
	const [searchParams] = useSearchParams();

	const { infinityScrollOffset } = useCommonSlice();

	const { data: notificationsResponse, isFetching } = useNotificationsListQuery({
		...getUrlParamsForApi(searchParams),
		...(infinityScrollOffset && { offset: infinityScrollOffset }),
	});
	const notifications = notificationsResponse?.results || [];
	const total = notificationsResponse?.count || 0;

	const { data: unread } = useNotificationsUnreadCountRetrieveQuery();
	const { readNotifications } = useSelector((s: RootState) => s.notificationsSlice);

	const loadMoreRef = useRef(null);
	const isNewFilter = getFilterValue(EFilters.READ) === 'false';

	useInfinityScroll(loadMoreRef, total, EPagination.MIN, isNewFilter ? Object.keys(readNotifications).length : 0);

	useEffect(() => {
		dispatch(clearReadNotifications());
	}, [isNewFilter, dispatch]);

	const onMarkAll = () => {
		const notificationsOnScreen = notifications.map((notification) => notification.id);
		dispatch(setReadNotifications(notificationsOnScreen));
		setRead({ ids: [] });
	};

	return {
		t,
		isMobile,
		getALLFilterValues,
		notifications,
		total,
		isFetching,
		unread,
		loadMoreRef,
		navigate,
		onFilterChange,
		appendReadNotification,
		setRead,
		onMarkAll,
	};
};
